"""Shared ``lib/`` import cache for snapshot Python (tools and hooks).

Tool and hook loaders both put the snapshot root on ``sys.path`` so
``from lib.helpers import x`` works. They must share one eviction set:
otherwise ``load_hooks`` would drop ``lib`` modules that tools just imported
during the same model load.
"""

from __future__ import annotations

import sys
from typing import Set

_snapshot_lib_module_names: Set[str] = set()


def evict_snapshot_lib_modules() -> None:
    """Drop ``lib`` / ``lib.*`` modules recorded by a previous snapshot load."""
    for module_name in _snapshot_lib_module_names:
        sys.modules.pop(module_name, None)
    _snapshot_lib_module_names.clear()


def record_snapshot_lib_modules() -> None:
    """Remember top-level ``lib`` modules currently in ``sys.modules``."""
    _snapshot_lib_module_names.update(
        name for name in sys.modules if name == "lib" or name.startswith("lib.")
    )
